function readState(){try{const raw=localStorage.getItem('future100_state');return raw?JSON.parse(raw):{};}catch(e){try{localStorage.removeItem('future100_state')}catch(_e){};return {};}}
const state=readState(); state.done=state.done||{};state.scores=state.scores||{};state.repeat=state.repeat||{};state.correct=state.correct||0;state.streak=state.streak||0;state.mastery=state.mastery||{};state.study=state.study||{lesson:0,phase:'learn',answers:0};state.chapter=state.chapter||{};
const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
function save(){try{localStorage.setItem('future100_state',JSON.stringify(state));}catch(e){console.error('تعذر حفظ تقدم الطالب',e);toast('تعذر حفظ التقدم على الجهاز ⚠️');} updateStats(); renderMemory();}
function updateStats(){const a=$('#lessonDone'),b=$('#correct'),c=$('#streak');if(a)a.textContent=Object.keys(state.done).length;if(b)b.textContent=state.correct;if(c)c.textContent=state.streak;}
function toast(t){const el=$('#toast');if(!el)return;el.textContent=t;el.classList.add('show');setTimeout(()=>el.classList.remove('show'),2200)}
function esc(v){return String(v??'').replace(/[&<>\"]/g,function(ch){return {'&':'&amp;','<':'&lt;','>':'&gt;','\\"':'&quot;'}[ch]||ch})}
function setView(v){try{if(v!=='exam'){try{if(typeof stopMinisterialTimer==='function')stopMinisterialTimer();}catch(_e){} try{if(typeof stopNightTimer==='function')stopNightTimer();}catch(_e){}}document.querySelectorAll('.view').forEach(function(x){x.classList.remove('active')});var target=document.getElementById(v);if(!target){try{toast('تعذر فتح هذه الصفحة');}catch(_e){}return false;}target.classList.add('active');document.querySelectorAll('.navbtn').forEach(function(b){b.classList.toggle('active',b.dataset.view===v)});try{if(v==='lessons'&&typeof renderCards==='function')renderCards();}catch(e){console.error('lessons render:',e)}try{if(v==='memory'&&typeof renderMemory==='function')renderMemory();}catch(e){console.error('memory render:',e)}try{if(v==='home'&&typeof renderToday==='function')renderToday();}catch(e){console.error('home render:',e)}try{if(v==='book'&&typeof loadBook==='function')loadBook(window.bookKey||'front');}catch(e){console.error('book render:',e)}try{if(v==='mistakes'&&typeof showMistakes==='function')showMistakes();}catch(e){console.error('mistakes render:',e)}return true;}catch(e){console.error('setView:',e);return false;}}
document.querySelectorAll('.navbtn[data-view]').forEach(b=>b.onclick=()=>setView(b.dataset.view));
let selected='الكل'; $$('[data-sub]').forEach(b=>b.onclick=()=>{selected=b.dataset.sub;$$('[data-sub]').forEach(x=>x.classList.toggle('active',x===b));setView('lessons');renderCards()});
$('#search').oninput=renderCards; if($('#bookSearch')) $('#bookSearch').oninput=searchBook;
function filtered(){let q=($('#search')?.value||'').trim();return lessons.filter(l=>(selected==='الكل'||l.subject===selected)&&(!q||l.title.includes(q)||l.chapter.includes(q)||l.summary.includes(q)));}
function renderCards(){let arr=filtered();$('#cards').innerHTML=arr.map(l=>'<article class="lesson"><span class="tag">'+l.subject+' • '+l.unit+'</span><h3>'+l.id+'. '+l.title+'</h3><p>'+l.summary+'</p><div class="progress"><div class="bar" style="width:'+(state.done[l.id]?100:0)+'%"></div></div><div class="actions"><button class="primary" onclick="startStudy('+l.id+')">'+(state.done[l.id]?'مراجعة الدرس':'ابدأ الدرس')+' ←</button><button class="ghost" onclick="startQuizFor('+l.id+')">سؤال</button></div></article>').join('')||'<div class="empty">لا توجد نتائج.</div>';}
async function startMasteryMission(){
  const L=window.Future100Learning;
  if(!L||!L.lessonQuestions){toast('نظام الإتقان غير جاهز حالياً.');return;}
  toast('جاري تجهيز مهمتك الذكية 🚀');
  const rows=[];
  for(const lesson of lessons){
    try{
      // حمّل بنك الدرس أولاً؛ lessonQuestions يعتمد على cache ولا يبني المحتوى بنفسه.
      await L.loadLessonBank(lesson.id);
      const qs=L.lessonQuestions(lesson.id);
      for(const q of qs){
        const s=L.questionState?L.questionState(q):null;
        const mastery=s&&typeof s.mastery==='number'?s.mastery:0;
        const due=s&&s.nextReview&&s.nextReview<=Date.now();
        const wrong=s&&s.wrong||0;
        let priority=(due?10000:0)+(wrong*250)+(100-mastery)*10+(s&&s.attempts?0:500);
        rows.push({...q,_priority:priority,lessonTitle:lesson.title});
      }
    }catch(e){}
  }
  const seen=new Set(), pool=[];
  rows.sort((a,b)=>b._priority-a._priority);
  for(const q of rows){
    const key=q.id||q.q;
    if(seen.has(key))continue;
    seen.add(key);pool.push(q);
    if(pool.length>=20)break;
  }
  if(!pool.length){toast('لا توجد أسئلة متاحة لهذه المهمة.');return;}
  window.masteryMission={questions:pool,i:0,score:0,before:Number(L.masteryPercent?L.masteryPercent():0)||0};
  setView('quiz');
  renderQuiz(pool);
  toast('بدأت مهمة الإتقان: 20 سؤالاً، والأضعف أولاً 🎯');
}
function openMasteryMap(){
  var page=document.getElementById('masteryMap');
  var box=document.getElementById('masteryMapContent');
  var summary=document.getElementById('masterySummary');

  if(!page||!box||!summary){
    var t=document.getElementById('toast');
    if(t){t.textContent='خريطة الإتقان غير موجودة في الصفحة ⚠️';t.classList.add('show');}
    return false;
  }

  try{
    document.querySelectorAll('.view').forEach(function(v){v.classList.remove('active');});
    page.classList.add('active');

    var list=Array.isArray(window.Future100LessonList)?window.Future100LessonList:
             (typeof lessons!=='undefined'&&Array.isArray(lessons)?lessons:[]);

    if(!list.length){
      box.innerHTML='<div class="empty">لم يتم تحميل الدروس بعد. أعد تحميل الصفحة مرة واحدة.</div>';
      summary.innerHTML='<div class="kpi"><b>0</b><span>درس محمّل</span></div>';
      return false;
    }

    var rows=[];
    list.forEach(function(l){
      var s={total:0,mastery:0,due:0,mistakes:0,ministerial:0};
      try{
        if(window.Future100Learning && typeof window.Future100Learning.lessonStats==='function'){
          var got=window.Future100Learning.lessonStats(Number(l.id));
          if(got && typeof got==='object')s=got;
        }
      }catch(err){ console.warn('lessonStats:',err); }

      rows.push({
        id:Number(l.id)||0,
        subject:String(l.subject||''),
        title:String(l.title||''),
        total:Number(s.total)||0,
        mastery:Number(s.mastery)||0,
        due:Number(s.due)||0,
        mistakes:Number(s.mistakes)||0,
        ministerial:Number(s.ministerial)||0
      });
    });

    var html='';
    rows.forEach(function(x){
      var p=Math.max(0,Math.min(100,Math.round(x.mastery)));
      var label=p>=90?'🟢 ممتاز':p>=70?'🟡 جيد':'🔴 يحتاج دراسة';
      html+='<article class="lesson" style="padding:14px">'+
        '<div style="display:flex;justify-content:space-between;gap:8px;align-items:center">'+
          '<div><span class="tag">'+x.id+' • '+x.subject+'</span><h3 style="margin:7px 0">'+x.title+'</h3></div>'+
          '<b style="font-size:22px">'+p+'%</b>'+
        '</div>'+
        '<div class="progress"><div class="bar" style="width:'+p+'%"></div></div>'+
        '<div class="small" style="margin-top:8px">'+label+' • '+x.total+' سؤال • '+x.due+' مستحق للتكرار • '+x.mistakes+' خطأ'+
          (x.ministerial?' • '+x.ministerial+' وزاري موثّق':'')+
        '</div>'+
        '<div class="actions">'+
          '<button class="primary" type="button" data-map-open="'+x.id+'">فتح الدرس</button>'+
          '<button class="ghost" type="button" data-map-quiz="'+x.id+'">اختبرني الآن</button>'+
        '</div>'+
      '</article>';
    });

    box.innerHTML='<div style="display:grid;gap:10px">'+html+'</div>';

    box.querySelectorAll('[data-map-open]').forEach(function(b){
      b.addEventListener('click',function(){
        var id=Number(b.getAttribute('data-map-open'));
        if(typeof window.openLesson==='function')window.openLesson(id);
      });
    });
    box.querySelectorAll('[data-map-quiz]').forEach(function(b){
      b.addEventListener('click',function(){
        var id=Number(b.getAttribute('data-map-quiz'));
        if(typeof window.startQuizFor==='function')window.startQuizFor(id);
      });
    });

    var totalMastery=rows.reduce(function(a,x){return a+x.mastery;},0);
    var avg=rows.length?Math.round(totalMastery/rows.length):0;
    var due=rows.filter(function(x){return x.due>0;}).length;
    var strong=rows.filter(function(x){return x.mastery>=90;}).length;

    summary.innerHTML=
      '<div class="kpi"><b>'+rows.length+'</b><span>درس</span></div>'+
      '<div class="kpi"><b>'+avg+'%</b><span>متوسط الإتقان</span></div>'+
      '<div class="kpi"><b>'+due+'</b><span>يحتاج تكرار</span></div>'+
      '<div class="kpi"><b>'+strong+'</b><span>إتقان 90%+</span></div>';

    var toastEl=document.getElementById('toast');
    if(toastEl){toastEl.textContent='تم فتح خريطة الإتقان ✅';toastEl.classList.add('show');setTimeout(function(){toastEl.classList.remove('show');},2200);}
    return true;
  }catch(err){
    console.error('Future100 mastery map error:',err);
    box.innerHTML='<div class="empty">تعذر عرض الخريطة حالياً. حاول إعادة تحميل الصفحة.</div>';
    var msg=err&&err.message?err.message:'خطأ غير معروف';
    var toastEl2=document.getElementById('toast');
    if(toastEl2){toastEl2.textContent='خطأ خريطة الإتقان: '+msg;toastEl2.classList.add('show');}
    return false;
  }
}
window.openMasteryMap=openMasteryMap;

function renderMasteryRows(rows){
  return '<div style="display:grid;gap:10px">'+rows.map(function(x){
    const p=Math.max(0,Math.min(100,x.mastery||0));
    const label=p>=90?'🟢 ممتاز':p>=70?'🟡 جيد':'🔴 يحتاج دراسة';
    return '<article class="lesson" style="padding:14px"><div style="display:flex;justify-content:space-between;gap:8px;align-items:center"><div><span class="tag">'+x.id+' • '+String(x.subject||'')+'</span><h3 style="margin:7px 0">'+String(x.title||'')+'</h3></div><b style="font-size:22px">'+p+'%</b></div><div class="progress"><div class="bar" style="width:'+p+'%"></div></div><div class="small" style="margin-top:8px">'+label+' • '+(x.total||0)+' سؤال • '+(x.due||0)+' مستحق للتكرار • '+(x.mistakes||0)+' خطأ'+(x.ministerial?' • '+x.ministerial+' وزاري موثّق':'')+'</div><div class="actions"><button class="primary" onclick="openLesson('+x.id+')">فتح الدرس</button><button class="ghost" onclick="startQuizFor('+x.id+')">اختبرني الآن</button></div></article>';
  }).join('')+'</div>';
}
function lessonMinisterial(id){var qs=(window.Future100MinisterialBank&&window.Future100MinisterialBank.byLesson?window.Future100MinisterialBank.byLesson(id):[]).filter(function(q){return q.verified===true;});if(!qs.length){toast('لا توجد وزاريات موثقة لهذا الدرس حالياً.');return;}ministryQuiz(qs,'وزاريات '+(lessons.find(function(x){return x.id===id})||{}).title+' 🏆');}
function openLesson(id){let l=lessons.find(x=>x.id===id);if(!l)return;setView('lessonView');var qs=(window.Future100MinisterialBank&&window.Future100MinisterialBank.byLesson?window.Future100MinisterialBank.byLesson(id):[]).filter(function(q){return q.verified===true;});var mastery=qs.length?Math.round(qs.reduce(function(sum,q){return sum+(Future100Learning&&Future100Learning.ensure?Future100Learning.ensure(q).mastery||0:0);},0)/qs.length):0;var mistakes=qs.reduce(function(sum,q){return sum+(Future100Learning&&Future100Learning.ensure?Future100Learning.ensure(q).wrong||0:0);},0);$('#lessonContent').innerHTML=`<div class="lessonHead"><span class="tag">${l.subject} • ${l.chapter}</span><h2>${l.title}</h2><p>${l.summary}</p></div><div class="lessonBody"><h3>🏆 وزاريات هذا الدرس</h3><div class="examPanel"><div class="kpiGrid"><div class="kpi"><b>${qs.length}</b><span>سؤال وزاري موثّق</span></div><div class="kpi"><b>${mastery}%</b><span>إتقان الوزاريات</span></div><div class="kpi"><b>${mistakes}</b><span>إجابات خاطئة</span></div><div class="kpi"><b>${qs.length?Math.max(0,qs.length-Math.round(qs.length*mastery/100)):0}</b><span>تحتاج مراجعة</span></div></div><div style="margin-top:12px"><div class="sessionBar"><i style="width:${mastery}%"></i></div><small class="small">يتحدث الإتقان تلقائياً بعد كل إجابة.</small></div><div class="actions"><button class="primary" onclick="lessonMinisterial(${l.id})">▶ اختبرني بوزاريات الدرس</button><button class="ghost" onclick="setView('ministry');renderMinistryDashboard()">فتح بنك الوزاريات</button></div></div><h3>🎯 المطلوب للوزاري</h3><p>ركز على: <b>التعريفات، علل، عدد، قارن، أكمل الفراغ، صح وخطأ، الخرائط والمواقع والأرقام</b> بحسب طبيعة هذا الدرس.</p><h3>🧠 دورة التثبيت</h3><p>اقرأ الفكرة مرة، أغلق الشرح، حاول استرجاعها بصوتك، ثم حل السؤال. إذا أخطأت لا تعتبرها فشلاً؛ سجّلها للتكرار.</p><div class="memory"><div class="m"><b>فهم</b><br><span class="small">اقرأ الملخص</span></div><div class="m"><b>استرجاع</b><br><span class="small">أجب بدون النظر</span></div><div class="m"><b>تكرار</b><br><span class="small">راجع حسب الضعف</span></div></div><div class="actions"><button class="primary" onclick="startQuizFor(${l.id})">ابدأ أسئلة الدرس ←</button><button class="ghost" onclick="completeLesson(${l.id})">تمت المراجعة ✓</button></div></div>`;}
function completeLesson(id){state.done[id]=Date.now();state.streak=Math.max(state.streak,1);save();toast('تم تسجيل الدرس كمكتمل ✅');setView('lessons');renderCards()}
