let current=[];let qi=0;let quizGradeLocked=false;function renderQuiz(arr){current=Array.isArray(arr)?arr.filter(Boolean):[];qi=0;quizGradeLocked=false;if(!current.length){setView('quiz');$('#quizContent').innerHTML='<div class="empty">لا توجد أسئلة متاحة حالياً.</div>';return}showQ()}
function showQ(){let x=current[qi];if(!x){$('#quizContent').innerHTML='<div class="empty">انتهت الأسئلة. عد إلى المراجعة.</div>';return}quizGradeLocked=false;$('#quizContent').innerHTML=`<div class="quizcard"><div class="qnum">سؤال ${qi+1} من ${current.length} • ${x.type||'مراجعة'}</div><h2>${x.q}</h2><div class="answer"><button class="primary" onclick="reveal()">أظهر الإجابة</button></div><div id="res" class="result"></div></div>`}
function reveal(){let x=current[qi];$('#res').className='result good';$('#res').innerHTML='<b>الإجابة النموذجية:</b><br>'+x.a+'<br><br><button class="primary" onclick="grade(true)">عرفتها ✓</button> <button class="ghost" onclick="grade(false)">كنت مخطئاً</button>';}
function grade(ok){if(quizGradeLocked)return;quizGradeLocked=true;let x=current[qi];state.correct+=ok?1:0;state.streak++;if(!ok){let key=x.q;state.repeat[key]=(state.repeat[key]||0)+1;}if(window.Future100Learning)Future100Learning.record(x,ok);save();if(window.masteryMission){window.masteryMission.score+=ok?1:0;if(qi<current.length-1){qi++;showQ();return;}var m=window.masteryMission;var after=Number(Future100Learning.masteryPercent?Future100Learning.masteryPercent():0)||0;var html='<div class="card"><h2>🚀 مهمة الإتقان انتهت</h2><div class="heroScore">'+(m.score||0)+' / '+current.length+'</div><p>الإتقان العام: '+m.before+'% → '+after+'%</p><p>تم تسجيل إجاباتك وتحديث التكرار الذكي تلقائياً.</p><button class="primary" onclick="startMasteryMission()">🔁 كرر المهمة</button><button class="secondary" onclick="openMasteryMap()">🗺️ خريطة الإتقان</button></div>';$('#quizContent').innerHTML=html;delete window.masteryMission;return;}if(!ok&&x.verified===true){x._retryCount=(x._retryCount||0)+1;if(x._retryCount<=2){let insertAt=Math.min(qi+3,current.length);current.splice(insertAt,0,x);toast('تم تسجيل الخطأ ❌ وسيعود السؤال بعد قليل 🔁');}}if(qi<current.length-1){qi++;showQ()}else{toast('انتهت المراجعة 🎯');setView('memory')}}
