function subjectQuestions(subject){
 return quizBank.filter(function(q){var t=q.q+' '+q.a;
  if(subject==='الجغرافية')return /العراق|الموقع|الحدود|التضاريس|السكان|التجارة|المناخ|المياه|الزراعة|الكثافة/.test(t);
  if(subject==='التاريخ')return /بريطانيا|العثمان|الحرب|العصبة|المجلس|فيصل|1924|1932|1941/.test(t);
  return /القيم|المواطنة|العلاقات|الإنترنت|الممتلكات|الحقوق|الواجبات|التواصل/.test(t);});
}
function nextUnfinished(){return lessons.find(function(l){return !state.done[l.id]})||lessons[0]}
function startStudy(id){var l=lessons.find(function(x){return x.id===id})||nextUnfinished();study={lessonId:l.id,phase:'learn',qIndex:0,score:0,questions:subjectQuestions(l.subject).slice(0,4)};setView('study');renderStudy()}
function renderStudy(){
 var l=lessons.find(function(x){return x.id===study.lessonId})||lessons[0],phase=study.phase,steps=['افهم','استرجع','اختبر'];
 var pills=steps.map(function(x,i){var a=(phase==='learn'&&i===0)||(phase==='recall'&&i===1)||(phase==='test'&&i===2);return '<b class="'+(a?'active':'')+'">'+(i+1)+'. '+x+'</b>'}).join(''),body='';
 if(phase==='learn')body='<h3>🧠 افهمها بسرعة</h3><div class="fact">'+l.summary+'</div><div class="recall">اقرأ الفكرة مرة، ثم حاول تقولها بكلامك بدون ما ترجع للنص.</div><div class="actions"><button class="primary" onclick="studyRecall()">فهمت — اختبرني ←</button></div>';
 else if(phase==='recall')body='<h3>🔁 استرجاع بدون النظر</h3><div class="fact">ما الفكرة الأساسية التي تعلمتها من درس «'+l.title+'»؟</div><p class="small">جاوب في بالك أو بصوتك، ثم اضغط للتأكد.</p><div class="actions"><button class="primary" onclick="studyTest()">جاهز للاختبار ←</button></div>';
 else {var qs=study.questions.length?study.questions:[{q:'ما الفكرة الأساسية في هذا الدرس؟',a:l.summary,type:'تدريب'}],q=qs[study.qIndex%qs.length],opts=[q.a,'إجابة غير صحيحة للتدريب','معلومة لا تتعلق بالدرس','لا توجد إجابة'].sort(function(){return Math.random()-.5});body='<div class="qnum">اختبار تثبيت '+(study.qIndex+1)+' من '+qs.length+'</div><h2>'+q.q+'</h2><div class="studyOptions">'+opts.map(function(o){return '<button class="studyOption" onclick=\'answerStudy(this,'+JSON.stringify(o===q.a)+','+JSON.stringify(q.q)+')\'>'+o+'</button>'}).join('')+'</div><div class="sourceNote">اختبار تثبيت تدريبي من قاعدة المحتوى، وليس سؤالاً وزارياً.</div>'}
 $('#studyContent').innerHTML='<div class="studyShell"><div class="studyTop"><button class="ghost" onclick="setView(\'home\')">← خروج</button><div class="phase">'+pills+'</div></div><div class="studyCard"><span class="tag">'+l.subject+' • '+l.unit+'</span><h2>'+l.title+'</h2>'+body+'</div></div>';
}
