function studyTest(){study.phase='test';study.qIndex=0;renderStudy()}
function answerStudy(btn,ok,q){$('.studyOption').forEach(function(x){x.disabled=true});btn.classList.add(ok?'correct':'wrong');recordMastery(q,ok);if(!ok)state.repeat[q]=(state.repeat[q]||0)+1;if(window.Future100Learning)Future100Learning.record({q:q,a:btn.textContent,type:'تدريب'},ok);study.score+=ok?1:0;study.qIndex++;save();setTimeout(function(){if(study.qIndex>=Math.min(4,study.questions.length||1)){var l=lessons.find(function(x){return x.id===study.lessonId});state.done[l.id]=Date.now();save();toast('تم تثبيت الدرس ✅');setView('lessons');renderCards()}else renderStudy()},450)}
function startChapterTest(subject){var sub=subject||'الجغرافية',qs=subjectQuestions(sub).slice(0,10);if(!qs.length){toast('لا توجد أسئلة تدريبية كافية لهذا القسم');return}study={lessonId:null,phase:'test',qIndex:0,score:0,questions:qs};setView('chapter');renderChapter(sub)}
function renderChapter(subject){var q=study.questions[study.qIndex],opts=[q.a,'إجابة غير صحيحة','إجابة غير مرتبطة بالدرس','لا شيء مما سبق'].sort(function(){return Math.random()-.5});$('#chapterContent').innerHTML='<div class="chapterShell"><div class="chapterCard"><div class="studyTop"><span class="tag">📚 اختبار الفصل — '+subject+'</span><b>'+(study.qIndex+1)+'/'+study.questions.length+'</b></div><h2>'+q.q+'</h2><div class="studyOptions">'+opts.map(function(o){return '<button class="studyOption" onclick=\'answerChapter(this,'+JSON.stringify(o===q.a)+','+JSON.stringify(q.q)+','+JSON.stringify(subject)+')\'>'+o+'</button>'}).join('')+'</div><div class="sourceNote">اختبار تدريبي مبني على محتوى الكتاب. الأسئلة الأصلية للفصل تبقى مرجعاً منفصلاً.</div></div></div>'}
function answerChapter(btn,ok,q,subject){$('.studyOption').forEach(function(x){x.disabled=true});btn.classList.add(ok?'correct':'wrong');recordMastery(q,ok);if(!ok)state.repeat[q]=(state.repeat[q]||0)+1;study.score+=ok?1:0;save();setTimeout(function(){study.qIndex++;if(study.qIndex<study.questions.length)renderChapter(subject);else{$('#chapterContent').innerHTML='<div class="chapterCard"><h2>🎯 انتهى الاختبار</h2><div class="fact">'+study.score+' / '+study.questions.length+'</div><p>تم تسجيل نقاط الضعف حتى يعيدها لك النظام.</p><button class="primary" onclick="showMistakes()">راجع أخطائي ←</button></div>'}},350)}
function showSmartReview(){
  try{
    var lm=window.Future100Learning;
    var due=[];
    if(lm&&typeof lm.buildReview==='function'&&typeof ministryPool==='function'){
      due=lm.buildReview(ministryPool()).filter(function(q){return q&&q.verified===true;});
    }
    if(due.length&&typeof ministryQuiz==='function'){
      ministryQuiz(due,'المراجعة الذكية للوزاريات 🧠');
      return;
    }
    if(typeof startWeakTest==='function'){
      startWeakTest();
      return;
    }
    if(typeof showMistakes==='function'){
      showMistakes();
      toast('ماكو أسئلة مراجعة جاهزة حالياً؛ عرضنا سجل الأخطاء.');
      return;
    }
    toast('المراجعة الذكية غير جاهزة حالياً. حدّث الصفحة وحاول مرة ثانية.');
  }catch(err){
    console.error('Smart review error:',err);
    try{if(typeof startWeakTest==='function')startWeakTest();else toast('تعذر تشغيل المراجعة الذكية.');}catch(_e){toast('تعذر تشغيل المراجعة الذكية.');}
  }
}
