function startWeakTest(){var lm=window.Future100Learning,smart=lm&&lm.mistakes?lm.mistakes():[];if(smart.length){var qs=smart.slice(0,15).map(function(x){return {id:x.id,q:x.question,a:x.answer,type:x.category||'نقطة ضعف',lessonId:x.lessonId,verified:x.verified===true};});setView('quiz');renderQuiz(qs);toast('اختبار نقاط الضعف: '+qs.length+' سؤال 🔥');return;}var qs=Object.keys(state.mastery||{}).filter(function(q){return state.mastery[q].wrong>0}).map(function(q){return quizBank.find(function(x){return x.q===q})}).filter(Boolean).slice(0,10);if(!qs.length){toast('لا توجد أسئلة ضعيفة حالياً');return}study={lessonId:null,phase:'test',qIndex:0,score:0,questions:qs};setView('chapter');renderChapter('نقاط ضعفي')}
