let bookCache={},bookPages=[],bookIndex=0,bookKey='geography';
async function loadBook(key='geography'){
 bookKey=key; document.querySelectorAll('.bookTab').forEach(b=>b.classList.toggle('active',b.dataset.book===key));
 const status=$('#bookStatus'); status.textContent='جاري تحميل الكتاب...';
 try{
  if(!bookCache[key]){const r=await fetch('book-'+key+'.txt',{cache:'force-cache'});if(!r.ok)throw new Error('HTTP '+r.status);bookCache[key]=await r.text();}
  const raw=bookCache[key],matches=[...raw.matchAll(/<PARSED TEXT FOR PAGE: (\d+) \/ 160>/g)];
  bookPages=matches.map((m,i)=>({page:Number(m[1]),text:raw.slice(m.index+m[0].length,i+1<matches.length?matches[i+1].index:raw.length).trim()}));
  bookIndex=0;renderBookPage();status.textContent='تم تحميل '+bookPages.length+' صفحة';
 }catch(e){status.textContent='تعذر تحميل الكتاب';$('#bookPage').textContent='تعذر تحميل ملف الكتاب. تأكد من نشر ملفات الكتاب مع الموقع.';console.error(e)}
}
function renderBookPage(){const p=bookPages[bookIndex];if(!p)return;$('#bookPage').textContent=p.text;$('#bookPageNo').textContent='صفحة '+p.page+' / '+bookPages.length;$('#bookResults').style.display='none'}
function bookNext(){if(bookIndex<bookPages.length-1){bookIndex++;renderBookPage()}}
function bookPrev(){if(bookIndex>0){bookIndex--;renderBookPage()}}
function searchBook(){const q=($('#bookSearch')?.value||'').trim();const box=$('#bookResults');if(!q){box.style.display='none';return}const hits=bookPages.map((p,i)=>({p,i})).filter(x=>x.p.text.includes(q)).slice(0,30);box.innerHTML=hits.length?hits.map(x=>'<button class="bookResult" onclick="bookIndex='+x.i+';renderBookPage()"><b>صفحة '+x.p.page+'</b> — '+x.p.text.replace(/\s+/g,' ').slice(0,150)+'</button>').join(''):'<div class="empty">لا توجد نتائج.</div>';box.style.display='block'}
