state.mastery=state.mastery||{};state.exam=state.exam||{attempts:0,best:0,last:0};
function masteryFor(q){return state.mastery[q]||{correct:0,wrong:0,level:0,next:0};}
function recordMastery(q,ok){const m=masteryFor(q);if(ok){m.correct++;m.level=Math.min(6,m.level+1)}else{m.wrong++;m.level=Math.max(0,m.level-2)}m.next=Date.now()+[0,1,2,4,7,14,30][m.level]*86400000;state.mastery[q]=m}
function startExam(){state.exam.attempts++;state.exam.current=examBank.slice().sort(()=>Math.random()-.5).slice(0,10);state.exam.i=0;state.exam.score=0;save();setView('exam');showExamQ()}
function showExamQ(){const e=state.exam,q=e.current[e.i],pct=Math.round(e.i/e.current.length*100);$('#examContent').innerHTML=`<div class="quizcard"><div class="qnum">اختبار 100 • السؤال ${e.i+1} من ${e.current.length}</div><div class="sessionBar"><i style="width:${pct}%"></i></div><h2>${q.q}</h2><div class="examOptions">${q.opts.map((o,i)=>`<button class="examOpt" onclick="pickExam(${i})">${String.fromCharCode(65+i)}. ${o}</button>`).join('')}</div><div id="examFeedback"></div></div>`}
function pickExam(i){const e=state.exam,q=e.current[e.i],buttons=$('.examOpt');buttons.forEach(b=>b.disabled=true);buttons[q.a].classList.add('correct');const ok=i===q.a;if(!ok)buttons[i].classList.add('wrong');if(ok)e.score++;recordMastery(q.q,ok);state.correct+=ok?1:0;save();$('#examFeedback').innerHTML=`<div class="feedback ${ok?'good':'bad'}"><b>${ok?'إجابة صحيحة ✅':'إجابة غير صحيحة ❌'}</b><br>${q.why}<br><button class="primary" style="margin-top:10px" onclick="nextExam()">${e.i+1===e.current.length?'إنهاء الاختبار':'السؤال التالي'} →</button></div>`}
function nextExam(){const e=state.exam;if(e.i<e.current.length-1){e.i++;showExamQ()}else{e.best=Math.max(e.best,e.score);e.last=Date.now();save();$('#examContent').innerHTML=`<div class="quizcard" style="text-align:center"><div style="font-size:58px">🏆</div><h2>انتهى الاختبار</h2><div class="kpiGrid"><div class="kpi"><b>${e.score}/10</b><span>النتيجة</span></div><div class="kpi"><b>${e.score*10}%</b><span>النسبة</span></div><div class="kpi"><b>${e.best}/10</b><span>أفضل نتيجة</span></div><div class="kpi"><b>${e.attempts}</b><span>المحاولات</span></div></div><button class="primary" style="margin-top:16px" onclick="startExam()">اختبار جديد 🔁</button><button class="ghost" style="margin-top:8px" onclick="setView('memory')">شوف نقاط ضعفك</button></div>`}}
function renderMemory(){const arr=Object.entries(state.mastery).sort((a,b)=>(a[1].next||0)-(b[1].next||0)).slice(0,12);const pct=Math.min(100,Math.round(Object.keys(state.done).length/lessons.length*100));$('#ring').style.setProperty('--pct',pct+'%');$('#ringText').textContent=pct+'%';$('#repeatList').innerHTML=arr.length?arr.map(([q,m])=>`<div class="rep"><span>${q}<br><span class="small">إتقان ${m.level}/6 • أخطاء ${m.wrong}</span></span><b>${m.next>Date.now()?'لاحقاً':'راجع الآن'}</b></div>`).join(''):'<div class="empty">ابدأ الاختبار حتى يتعلم النظام نقاط قوتك وضعفك.</div>'}
$('.navbtn').forEach(function(b){b.onclick=function(){try{if(b.dataset.view==='exam'){if(typeof startExam==='function')startExam();else setView('exam')}else setView(b.dataset.view);}catch(e){console.error('navigation:',e);}}});
renderToday();renderMemory();


