let examPlanState={days:7};
function openExamPlan(){
  try{
    setView('examPlan');
    const el=$('#examPlanContent');
    if(!el){toast('تعذر فتح صفحة الخطة ⚠️');return;}
    const days=Math.max(1,Math.min(60,Number((window.examPlanState&&examPlanState.days)||7)));
    el.innerHTML='<div class="card"><h2>📅 خطتك قبل الامتحان</h2><p>اختر عدد الأيام، وسأوزع لك الدروس حسب الضعف والأخطاء.</p><div class="actions"><input id="planDays" type="number" min="1" max="60" value="'+days+'" style="max-width:140px"><button class="primary" onclick="buildExamPlan()">🚀 بناء الخطة</button></div></div>';
  }catch(e){console.error(e);toast('تعذر فتح الخطة ⚠️');}
}
function buildExamPlan(){
  try{
    const el=$('#examPlanContent');
    const days=Math.max(1,Math.min(60,Number($('#planDays')&&$('#planDays').value)||7));
    window.examPlanState=window.examPlanState||{days:7};
    examPlanState.days=days;
    const rows=lessons.map(function(l){
      let s={total:0,mastery:0,due:0,mistakes:0};
      try{if(window.Future100Learning&&typeof Future100Learning.lessonStats==='function')s=Future100Learning.lessonStats(l.id)||s;}catch(e){}
      return Object.assign({},l,s);
    });
    rows.sort(function(a,b){return (Number(b.mistakes)||0)-(Number(a.mistakes)||0)||(Number(b.due)||0)-(Number(a.due)||0)||(Number(a.mastery)||0)-(Number(b.mastery)||0);});
    const per=Math.max(1,Math.ceil(rows.length/days));
    let html='<div class="card"><h2>خطة '+days+' يوم</h2><p>تم بناء الخطة من الدروس الـ62 بناءً على أخطائك وإتقانك.</p>';
    for(let d=0;d<days;d++){
      const chunk=rows.slice(d*per,(d+1)*per);
      if(!chunk.length)break;
      html+='<div class="card" style="margin:10px 0"><h3>📅 اليوم '+(d+1)+'</h3><p class="small">'+(d===days-1?'مراجعة شاملة + وزاريات + أخطاء':'فهم + استرجاع + تكرار للضعف')+'</p>';
      chunk.forEach(function(l){html+='<div class="rep"><span>'+l.id+'. '+l.title+'<small class="small"> • '+(l.total||0)+' سؤال • '+(l.mistakes||0)+' خطأ • '+(l.due||0)+' مستحق</small></span><b>'+Math.round(Number(l.mastery)||0)+'%</b></div>';});
      html+=(d===days-1?'<button class="primary" onclick="startMinisterialExam()">🏆 اختبار وزاري 100 درجة</button>':'<button class="ghost" onclick="startMasteryMission()">🚀 جلسة إتقان</button>')+'</div>';
    }
    html+='</div>';
    el.innerHTML=html;
    toast('تم بناء خطتك بنجاح ✅');
  }catch(e){console.error(e);toast('حدث خطأ أثناء بناء الخطة ⚠️');}
}

