/* STUDENT_ANALYTICS_AND_NIGHT_MODE */
function classifyQuestion(q){
  const s=(q.category||q.type||'')+' '+(q.q||q.question||'');
  if(/تعريف|المقصود|عرّف/.test(s))return 'تعريفات';
  if(/علل|فسر|سبب/.test(s))return 'علل/فسر';
  if(/عدد|اذكر|ما هي|ما هي أهم|أقسام/.test(s))return 'عدد/اذكر';
  if(/فراغ|أكمل|اكمل|________/.test(s))return 'فراغات';
  if(/صح|خطأ/.test(s))return 'صح وخطأ';
  if(/وزاري/.test(s))return 'وزاريات';
  return 'أسئلة الدرس';
}
async function collectStudentAnalytics(){
  const rows=[], types={};
  for(const l of lessons){
    try{
      await Future100Learning.loadLessonBank(l.id);
      const qs=Future100Learning.lessonQuestions(l.id);
      let total=0,wrong=0,mastery=0;
      qs.forEach(q=>{const st=Future100Learning.questionState(q)||{};const cat=classifyQuestion(q);types[cat]=types[cat]||{total:0,wrong:0,mastery:0};types[cat].total++;types[cat].wrong+=st.wrong||0;types[cat].mastery+=st.mastery||0;total++;wrong+=st.wrong||0;mastery+=st.mastery||0;});
      rows.push({...l,total,wrong,mastery:total?Math.round(mastery/total):0});
    }catch(e){rows.push({...l,total:0,wrong:0,mastery:0,error:true});}
  }
  Object.keys(types).forEach(k=>types[k].mastery=Math.round(types[k].mastery/Math.max(1,types[k].total)));
  return {rows,types};
}
async function openPerformance(){
  setView('performance');
  const box=$('#performanceContent');if(!box)return;
  box.innerHTML='<div class="empty">⏳ جاري تحليل 62 درساً وتصنيف الأسئلة…</div>';
  const a=await collectStudentAnalytics();
  const avg=a.rows.length?Math.round(a.rows.reduce((s,x)=>s+x.mastery,0)/a.rows.length):0;
  const weak=a.rows.filter(x=>x.mastery<60||x.wrong>=3).sort((x,y)=>(y.wrong-x.wrong)||(x.mastery-y.mastery));
  const types=Object.entries(a.types).sort((x,y)=>(x[1].mastery-y[1].mastery));
  const warning=weak.length?'<div class="warning critical">🚨 عندك '+weak.length+' درس يحتاج تدخل سريع. ابدأ بأعلى 5 أدناه.</div>':'<div class="warning">🟢 لا توجد أجزاء حرجة حالياً. استمر بالمراجعة.</div>';
  box.innerHTML='<div class="analyticsGrid"><div class="analyticsCard"><b>'+avg+'%</b><small>متوسط إتقان 62 درس</small></div><div class="analyticsCard"><b>'+weak.length+'</b><small>أجزاء ضعيفة</small></div><div class="analyticsCard"><b>'+Future100Learning.stats().wrong+'</b><small>إجمالي الأخطاء</small></div><div class="analyticsCard"><b>'+Future100Learning.stats().answered+'</b><small>إجمالي الإجابات</small></div></div>'+warning+'<h3>🎯 حسب نوع السؤال</h3>'+types.map(([k,v])=>'<div class="typeRow"><b>'+k+'</b><div class="typeBar"><i style="width:'+v.mastery+'%"></i></div><b>'+v.mastery+'%</b></div>').join('')+'<h3>🚨 الأجزاء التي تحتاج دراسة</h3><div class="auditList">'+(weak.length?weak.slice(0,12).map(x=>'<div class="auditItem"><span>'+x.id+'. '+x.title+'<small class="small"> • '+x.wrong+' خطأ • '+x.total+' سؤال</small></span><b class="'+(x.mastery<40?'badTag':'')+'">'+x.mastery+'%</b></div>').join(''):'<div class="empty">لا توجد نقاط ضعف حرجة.</div>')+'</div><div class="actions"><button class="primary" onclick="startWeakTest()">🔥 اختبرني بأضعف الأجزاء</button><button class="ghost" onclick="openMasteryMap()">🗺️ خريطة الـ62</button></div>';
}
