function ministryPool(){return (window.Future100MinisterialBank&&window.Future100MinisterialBank.all?window.Future100MinisterialBank.all():[]).filter(function(q){return q.verified===true;});}
function ministryState(){return {year:$('#minYear')&&$('#minYear').value||'',round:$('#minRound')&&$('#minRound').value||'',subject:$('#minSubject')&&$('#minSubject').value||'',chapter:$('#minChapter')&&$('#minChapter').value||'',lesson:$('#minLesson')&&$('#minLesson').value||''};}
function fillMinistrySelect(id,values,current){var el=$('#'+id);if(!el)return;var first=el.options[0]?el.options[0].textContent:'الكل';el.innerHTML='<option value="">'+first+'</option>'+values.map(function(v){return '<option value="'+String(v).replace(/"/g,'&quot;')+'">'+v+'</option>';}).join('');if(values.map(String).includes(String(current)))el.value=current;}
function ministryFiltered(){var all=ministryPool(),s=ministryState();return all.filter(function(q){return (!s.year||String(q.year)===s.year)&&(!s.round||q.round===s.round)&&(!s.subject||q.subject===s.subject)&&(!s.chapter||q.chapter===s.chapter);}).filter(function(q){if(!s.lesson)return true;var l=lessons.find(function(x){return x.id===q.lessonId;});return (l?l.title:String(q.lessonId))===s.lesson;});}
function renderMinistryDashboard(){var all=ministryPool(),old=ministryState();fillMinistrySelect('minYear',[...new Set(all.map(function(q){return q.year;}).filter(Boolean))].sort(function(a,b){return b-a;}),old.year);fillMinistrySelect('minRound',[...new Set(all.map(function(q){return q.round;}).filter(Boolean))],old.round);fillMinistrySelect('minSubject',[...new Set(all.map(function(q){return q.subject;}).filter(Boolean))],old.subject);var subject=$('#minSubject')&&$('#minSubject').value||'';var a=all.filter(function(q){return !subject||q.subject===subject;});fillMinistrySelect('minChapter',[...new Set(a.map(function(q){return q.chapter;}).filter(Boolean))],old.chapter);var chapter=$('#minChapter')&&$('#minChapter').value||'';var b=a.filter(function(q){return !chapter||q.chapter===chapter;});var lessonNames=[...new Set(b.map(function(q){var l=lessons.find(function(x){return x.id===q.lessonId;});return l?l.title:String(q.lessonId||'غير محدد');}))];fillMinistrySelect('minLesson',lessonNames,old.lesson);var qs=ministryFiltered();var years=new Set(all.map(function(q){return q.year;})),rounds=new Set(all.map(function(q){return q.round;}));$('#ministryTotal').textContent=all.length;$('#ministryYears').textContent=years.size;$('#ministryRounds').textContent=rounds.size;var mistakes=Future100Learning.mistakes(),ids=new Set(mistakes.map(function(x){return x.id;}));$('#ministryMistakes').textContent=all.filter(function(q){return ids.has(q.id);}).length;var vals=all.map(function(q){return Future100Learning.ensure(q).mastery||0;});$('#ministryMastery').textContent=(vals.length?Math.round(vals.reduce(function(a,b){return a+b;},0)/vals.length):0)+'%';$('#ministryCount').textContent='عرض '+qs.length+' من '+all.length+' سؤال موثّق';$('#ministryList').innerHTML=qs.length?qs.map(function(q){var m=Future100Learning.ensure(q),l=lessons.find(function(x){return x.id===q.lessonId;});return '<article class="ministryCard"><div class="ministryMeta"><span>📅 '+(q.year||'—')+'</span><span>🎯 '+(q.round||'—')+'</span><span>📚 '+(q.subject||'—')+'</span><span>✓ موثّق</span></div><h3>'+q.question+'</h3><p>'+((l&&l.title)||q.chapter||'وزاري')+'</p><div class="masteryLine"><i style="width:'+(m.mastery||0)+'%"></i></div><small>إتقان '+(m.mastery||0)+'% • خطأ '+(m.wrong||0)+' مرة</small></article>';}).join(''):'<div class="ministryEmpty">لا توجد أسئلة موثقة بهذه الفلاتر حالياً.<br>جرّب تغيير السنة أو الدور أو المادة.</div>';}
function ministryQuiz(qs,title){if(!qs.length){toast('لا توجد وزاريات موثقة مطابقة حالياً.');return;}setView('quiz');renderQuiz(qs.slice(0,20).map(function(q){return Object.assign({},q,{q:q.question,a:q.answer,type:'وزاري موثّق'});}));toast(title||('تم تجهيز '+Math.min(20,qs.length)+' سؤال وزاري'));}
function startMinisterialFilteredQuiz(){ministryQuiz(ministryFiltered(),'اختبار الوزاريات حسب اختيارك 🏆');}
function startMinisterialMistakes(){var ids=new Set(Future100Learning.mistakes().map(function(x){return x.id;}));ministryQuiz(ministryPool().filter(function(q){return ids.has(q.id);}),'وزاريات الأخطاء ❌');}
function startMinisterialDue(){ministryQuiz(Future100Learning.buildReview(ministryPool()).filter(function(q){return q.verified===true;}),'المراجعة الذكية للوزاريات 🧠');}
let ministerialPaper={gradeLocked:false,sections:[],i:0,score:0,answers:[]};
function startMinisterialPaper(){var pool=ministryPool().slice();if(pool.length<6){toast('نحتاج عدداً أكبر من الوزاريات الموثقة لبناء ورقة كاملة.');return;}var pick=function(arr,n){return arr.slice().sort(function(){return Math.random()-.5;}).slice(0,n);};var defs=pool.filter(function(q){return /عرّف/.test(q.question);}), counts=pool.filter(function(q){return /عدّد|اذكر|وضح/.test(q.question);}), reasons=pool.filter(function(q){return /علل/.test(q.question);}), others=pool.filter(function(q){return !defs.includes(q)&&!counts.includes(q)&&!reasons.includes(q);});ministerialPaper={sections:[{name:'س1 • التعاريف',qs:pick(defs,4)},{name:'س2 • تعداد وشرح',qs:pick(counts,2)},{name:'س3 • تعاليل',qs:pick(reasons,2)},{name:'س4 • مراجعة متنوعة',qs:pick(others.concat(defs,counts),2)}].filter(function(s){return s.qs.length;}).map(function(s){return s;}).flatMap(function(s){return s.qs.map(function(q){return Object.assign({},q,{section:s.name});});}),i:0,score:0,answers:[]};if(ministerialPaper.sections.length<6){toast('عدد الوزاريات الموثقة الحالي لا يكفي لمحاكاة الورقة كاملة. تم تشغيل اختبار وزاري بديل.');startMinisterialExam();return;}setView('exam');showMinisterialPaperQ();}
function showMinisterialPaperQ(){var p=ministerialPaper,q=p.sections[p.i],m=Future100Learning.ensure(q),pct=Math.round(p.i/p.sections.length*100);$('#examContent').innerHTML='<div class="quizcard"><div class="qnum">📄 محاكاة وزاري • '+q.section+' • سؤال '+(p.i+1)+' من '+p.sections.length+'</div><div class="sessionBar"><i style="width:'+pct+'%"></i></div><h2>'+q.question+'</h2><p class="small">السنة: '+(q.year||'—')+' • '+(q.round||'—')+'</p><button class="primary" onclick="revealMinisterialPaper()">أظهر الإجابة النموذجية</button><div id="paperFeedback"></div></div>';}
function revealMinisterialPaper(){var q=ministerialPaper.sections[ministerialPaper.i];$('#paperFeedback').innerHTML='<div class="feedback good"><b>الإجابة النموذجية:</b><br>'+q.answer+'<div class="actions"><button class="primary" onclick="gradeMinisterialPaper(true)">عرفتها ✓</button><button class="ghost" onclick="gradeMinisterialPaper(false)">أخطأت ✗</button></div></div>';}
function gradeMinisterialPaper(ok){var p=ministerialPaper,q=p.sections[p.i];if(!q||p.gradeLocked)return;p.gradeLocked=true;if(ok)p.score+=Math.round(100/p.sections.length);Future100Learning.record(q,ok);p.answers.push({q:q,ok:ok});save();if(p.i<p.sections.length-1){p.i++;showMinisterialPaperQ();}else{p.score=Math.min(100,p.score);var weak=p.answers.filter(function(x){return !x.ok;});$('#examContent').innerHTML='<div class="quizcard" style="text-align:center"><div style="font-size:56px">📄🏆</div><h2>انتهت المحاكاة</h2><div class="kpiGrid"><div class="kpi"><b>'+p.score+'/100</b><span>الدرجة</span></div><div class="kpi"><b>'+weak.length+'</b><span>أخطاء</span></div></div><p>'+ (weak.length?'راجع الأخطاء ثم أعد الاختبار.':'ممتاز، لم تسجل أخطاء! 🎯')+'</p><button class="primary" onclick="startMinisterialPaper()">محاكاة جديدة 🔁</button><button class="ghost" onclick="showMinistry()">بنك الوزاريات</button></div>';}}
let ministerialExam={questions:[],i:0,score:0,answers:[],chapters:{}};
var ministerialTimer=null,ministerialTimeLeft=0;
function stopMinisterialTimer(){if(ministerialTimer){clearInterval(ministerialTimer);ministerialTimer=null;}}
function startMinisterialTimer(minutes){stopMinisterialTimer();ministerialTimeLeft=minutes*60;ministerialTimer=setInterval(function(){ministerialTimeLeft--;var el=$('#examTimer');if(el){var mm=Math.floor(ministerialTimeLeft/60),ss=ministerialTimeLeft%60;el.textContent='⏱️ '+mm+':'+String(ss).padStart(2,'0');el.style.opacity=ministerialTimeLeft<=60?'1':'.85';}if(ministerialTimeLeft<=0){stopMinisterialTimer();toast('انتهى الوقت ⏰');finishMinisterialExam(true);}},1000);}
function startMinisterialExam(){var pool=(Future100Learning.smartMinisterial?Future100Learning.smartMinisterial():ministryPool().slice()).slice();if(!pool.length){toast('لا توجد وزاريات موثقة حالياً.');return;}ministerialExam={questions:pool.slice(0,20),i:0,score:0,answers:[],chapters:{},startedAt:Date.now(),gradeLocked:false};setView('exam');showMinisterialExamQ();startMinisterialTimer(30);}
function showMinisterialExamQ(){var e=ministerialExam,q=e.questions[e.i],m=Future100Learning.ensure(q),pct=Math.round(e.i/e.questions.length*100);$('#examContent').innerHTML='<div class="quizcard"><div style="display:flex;justify-content:space-between;gap:10px;align-items:center"><div class="qnum">🏆 محاكاة وزاري كاملة • السؤال '+(e.i+1)+' من '+e.questions.length+' • '+(q.year||'')+' '+(q.round||'')+'</div><b id="examTimer">⏱️ 30:00</b></div><div class="sessionBar"><i style="width:'+pct+'%"></i></div><h2>'+q.question+'</h2><div class="examPanel"><span class="pill blueP">الدرس: '+((lessons.find(function(l){return l.id===q.lessonId;})||{}).title||q.chapter||'غير محدد')+'</span><p class="small">إتقانك الحالي: '+(m.mastery||0)+'% • أخطاء: '+(m.wrong||0)+'</p><label class="small" style="display:block;margin:12px 0 7px">✍️ اكتب إجابتك — لن تظهر الإجابة النموذجية أثناء الامتحان</label><textarea id="ministerialAnswer" rows="6" placeholder="اكتب إجابتك هنا..." style="width:100%;resize:vertical;padding:12px;border-radius:10px;background:#061522;border:1px solid #1c4965;color:white;line-height:1.9;outline:none"></textarea><button class="primary" onclick="submitMinisterialAnswer()">تسليم الإجابة ←</button><div id="ministerialExamFeedback"></div></div></div>';}
function submitMinisterialAnswer(){var e=ministerialExam,q=e.questions[e.i],el=$('#ministerialAnswer');if(!el)return;var answer=el.value.trim();if(!answer){toast('اكتب إجابتك أولاً ✍️');return;}el.disabled=true;var btn=el.nextElementSibling;if(btn)btn.disabled=true;$('#ministerialExamFeedback').innerHTML='<div class="feedback" style="background:#09243a;border:1px solid #17668d"><b>تم تسليم الإجابة ✓</b><br><span class="small">الآن فقط يمكنك مقارنة إجابتك بالإجابة النموذجية.</span><div style="margin-top:10px"><b>الإجابة النموذجية:</b><br>'+q.answer+'</div><div class="actions"><button class="primary" onclick="gradeMinisterialExam(true)">إجابتي صحيحة ✓ +5</button><button class="ghost" onclick="gradeMinisterialExam(false)">إجابتي خاطئة ✗ +0</button></div></div>';}
function gradeMinisterialExam(ok){var e=ministerialExam,q=e.questions[e.i];if(!q||e.gradeLocked)return;e.gradeLocked=true;if(ok)e.score+=5;else{var key=q.id||q.question;state.repeat[key]=(state.repeat[key]||0)+1;}if(window.Future100Learning)Future100Learning.record(q,ok);save();var chapter=q.chapter||'غير محدد';e.chapters[chapter]=(e.chapters[chapter]||0)+(ok?5:0);e.answers.push({q:q,ok:ok});if(e.i<e.questions.length-1){e.i++;showMinisterialExamQ();}else{finishMinisterialExam();}}
function finishMinisterialExam(timeUp){stopMinisterialTimer();var e=ministerialExam;if(timeUp&&e.i<e.questions.length){for(var j=e.i;j<e.questions.length;j++){var uq=e.questions[j];if(!e.answers.some(function(x){return (x.q.id||x.q.question)===(uq.id||uq.question);}))e.answers.push({q:uq,ok:false,unanswered:true}),Future100Learning.record(uq,false);}}var level=e.score>=90?'ممتاز جداً 🏆':e.score>=80?'ممتاز 🔥':e.score>=70?'جيد جداً 💪':e.score>=60?'جيد 👍':'تحتاج مراجعة 🧠';var weak=e.answers.filter(function(x){return !x.ok;});var answered=e.answers.filter(function(x){return !x.unanswered;}).length;$('#examContent').innerHTML='<div class="quizcard" style="text-align:center"><div style="font-size:58px">'+(e.score>=80?'🏆':'📚')+'</div><h2>'+ (timeUp?'⏰ انتهى الوقت — ':'') +'نتيجة المحاكاة الوزارية</h2><div class="kpiGrid"><div class="kpi"><b>'+e.score+'/100</b><span>الدرجة</span></div><div class="kpi"><b>'+level+'</b><span>التقييم</span></div><div class="kpi"><b>'+weak.length+'</b><span>أخطاء/غير مجاب</span></div><div class="kpi"><b>'+answered+'/'+e.questions.length+'</b><span>تمت الإجابة</span></div></div><div class="examPanel" style="text-align:right"><h3>📊 نقاط الضعف</h3>'+ (weak.length?weak.slice(0,20).map(function(x){return '<div class="rep"><span>'+x.q.question+(x.unanswered?' <small class="badTag">• بدون إجابة</small>':'')+'</span><b>✗</b></div>';}).join(''):'<p>رائع! لم تخطئ بأي سؤال 🎯</p>')+'</div><div class="actions"><button class="primary" onclick="startMinisterialExam()">محاكاة جديدة 🔁</button><button class="primary" onclick="startMinisterialMistakes()">راجع الأخطاء ❌</button><button class="ghost" onclick="openPerformance()">تحليل أدائي 📊</button></div></div>';}

